const PETALS = Array.from({ length: 16 }, (_, index) => index * 22.5);

function Eye({ x, kind }: { x: number; kind: Eyes }) {
  if (kind === 'closed') return <path d={`M${x - 11} 190q11-11 22 0`} className="face-line" />;
  const ry = kind === 'wide' ? 13 : kind === 'half' ? 6 : 10;
