.studio-grid.sidebar-collapsed {
  grid-template-columns: 0px minmax(400px, 1fr) 400px;
  gap: 0 40px;
}

.studio-grid.sidebar-collapsed .scenario-panel {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  padding: 0;
  border: none;
}

/* Stage Maximized Variation */
.studio-grid.stage-maximized {
  grid-template-columns: 1fr;
