  padding-top: 12px;
}

.stage-orbit {
  position: absolute;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.05) 0%, transparent 70%);
  border: 1px dashed rgba(15, 23, 42, 0.08);
  top: 10px;
  pointer-events: none;
}

