  height: 290px;
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.aura-stage-wrapper {
  position: relative;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Deep void disc background gives LiveKit's WebGL bloom shader cinematic contrast */
  background: radial-gradient(circle at center, #070b14 0%, #03060a 100%);
  box-shadow:
