  filter: blur(28px);
  pointer-events: none;
  z-index: 0;
  transition: all 0.6s ease;
}

.aura-glow-backdrop.mood-neutral {
  background: radial-gradient(circle, rgba(31, 213, 249, 0.35) 0%, rgba(37, 99, 235, 0.15) 60%, transparent 80%);
