.aura-glow-backdrop.mood-friendly {
  background: radial-gradient(circle, rgba(16, 185, 129, 0.4) 0%, rgba(6, 182, 212, 0.15) 60%, transparent 80%);
}

.aura-glow-backdrop.mood-challenging {
  background: radial-gradient(circle, rgba(244, 63, 94, 0.45) 0%, rgba(249, 115, 22, 0.18) 60%, transparent 80%);
}

