.avatar-idle .aura-stage-wrapper {
  animation: aura-idle-breathe 6s ease-in-out infinite;
}

/* 2. LISTENING: Focused Expanding Field */
.avatar-listening .aura-stage-wrapper {
  transform: scale(1.04);
