  max-height: 760px;
}

/* SCENARIO PANEL */
.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  font-family: var(--font-mono);
  padding-bottom: 14px;
}

.scenario-list {
  display: flex;
  flex-direction: column;
  gap: 8px; /* 间距展开 */
  margin-top: 8px;
}

.scenario-card {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 13px;
  background: transparent;
  border: 1px solid transparent;
  text-align: left;
  border-radius: 14px;
  padding: 12px 14px; /* padding 展开 */
  color: var(--ink);
  transition: all 0.15s ease;
}
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
}

.stage-tool-btn:hover {
  background: rgba(15, 23, 42, 0.045);
  color: var(--ink);
}

.stage-tool-icon {
  padding: 6px 8px;
}

.difficulty-badge {
  text-transform: capitalize;
  font-size: 11px;
  font-weight: 600;
  background: #f1f5f9;
  padding: 4px 12px;
  border-radius: 20px;
  color: var(--muted);
  font-family: var(--font-mono);
}

/* NEXT-GEN IMMERSIVE AVATAR (PORTRAIT + MICRO-INTERACTION) */
.avatar-stage {
  position: relative;
  display: flex;
  align-items: center;
  flex-direction: column;
  padding-top: 12px;
}

.stage-orbit {
  position: absolute;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.05) 0%, transparent 70%);
  border: 1px dashed rgba(15, 23, 42, 0.08);
  top: 10px;
  pointer-events: none;
}

/* LIVEKIT AGENTS UI - FLUID SHADER AURA */
.avatar {
  width: 290px;
  height: 290px;
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.aura-stage-wrapper {
  position: relative;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Deep void disc background gives LiveKit's WebGL bloom shader cinematic contrast */
  background: radial-gradient(circle at center, #070b14 0%, #03060a 100%);
  box-shadow:
    0 16px 40px -8px rgba(2, 6, 23, 0.28),
    0 0 0 1px rgba(255, 255, 255, 0.08),
    inset 0 0 24px rgba(0, 0, 0, 0.6);
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s ease;
  overflow: visible;
}

.aura-visualizer-canvas {
  border-radius: 50%;
  pointer-events: none;
  z-index: 2;
}

/* Atmospheric Ambient Bloom behind the Disc */
.aura-glow-backdrop {
  position: absolute;
  inset: -14px;
  border-radius: 50%;
  opacity: 0.55;
  filter: blur(28px);
  pointer-events: none;
  z-index: 0;
  transition: all 0.6s ease;
}

.aura-glow-backdrop.mood-neutral {
  background: radial-gradient(circle, rgba(31, 213, 249, 0.35) 0%, rgba(37, 99, 235, 0.15) 60%, transparent 80%);
}

.aura-glow-backdrop.mood-friendly {
  background: radial-gradient(circle, rgba(16, 185, 129, 0.4) 0%, rgba(6, 182, 212, 0.15) 60%, transparent 80%);
}

.aura-glow-backdrop.mood-challenging {
  background: radial-gradient(circle, rgba(244, 63, 94, 0.45) 0%, rgba(249, 115, 22, 0.18) 60%, transparent 80%);
}

/* Outer Resonance Waves */
.aura-resonance-ring {
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  border: 1.5px solid transparent;
  pointer-events: none;
  z-index: 1;
  transition: all 0.4s ease;
}

/* --- STATE MICRO-INTERACTIONS --- */

/* 1. IDLE: Quiet Deep Breathing */
.avatar-idle .aura-stage-wrapper {
  animation: aura-idle-breathe 6s ease-in-out infinite;
}

/* 2. LISTENING: Focused Expanding Field */
.avatar-listening .aura-stage-wrapper {
  transform: scale(1.04);
}
.avatar-listening .aura-glow-backdrop {
  opacity: 0.85;
  inset: -22px;
}
.avatar-listening .aura-resonance-ring.mood-neutral {
  border-color: rgba(31, 213, 249, 0.4);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}
.avatar-listening .aura-resonance-ring.mood-friendly {
  border-color: rgba(16, 185, 129, 0.45);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}
.avatar-listening .aura-resonance-ring.mood-challenging {
  border-color: rgba(244, 63, 94, 0.45);
  animation: aura-ripple-wave 2s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}

/* 3. THINKING: Compact Swirling Core */
.avatar-thinking .aura-stage-wrapper {
  transform: scale(0.95);
}
.avatar-thinking .aura-glow-backdrop {
  opacity: 0.7;
}

/* 4. SPEAKING: Dynamic Expansion (大声变大) */
.avatar-speaking .aura-stage-wrapper {
  transform: scale(1.1);
  box-shadow:
    0 24px 50px -10px rgba(2, 6, 23, 0.35),
    0 0 0 1.5px rgba(255, 255, 255, 0.15),
    0 0 35px rgba(31, 213, 249, 0.25);
}
.avatar-speaking .aura-glow-backdrop {
  opacity: 1;
  inset: -28px;
}
.avatar-speaking .aura-resonance-ring {
  opacity: 0.6;
  animation: aura-speaking-wave 1.4s ease-out infinite;
}

@keyframes aura-idle-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.02); }
}

@keyframes aura-ripple-wave {
  0% { transform: scale(0.96); opacity: 0.8; }
  100% { transform: scale(1.15); opacity: 0; }
}

@keyframes aura-speaking-wave {
  0% { transform: scale(1); opacity: 0.8; }
  100% { transform: scale(1.2); opacity: 0; }
}

.stage-persona {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
  z-index: 1;
}

.counterpart-name {
  font-size: 18px; /* 名字字号展开 */
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.2px;
}

.state-indicator {
