.difficulty {
  border-top: 1px solid var(--border-hairline);
  padding-top: 20px;
  margin-top: 22px;
}

.difficulty label, .custom-label {
  font-weight: 650;
  font-size: 12px;
  color: var(--muted);
  display: block;
  margin-bottom: 7px;
}

.difficulty select {
  display: block;
  width: 100%;
  padding: 10px 12px; /* 展开尺寸 */
  margin-bottom: 16px;
  border: 1px solid var(--border-hairline);
  background: #ffffff;
  border-radius: 10px;
  font-size: 13.5px;
  color: var(--ink);
  transition: border-color 0.15s;
}

.difficulty select:focus {
  border-color: var(--blue);
  outline: none;
}

.custom-label {
  display: block;
  margin-top: 14px;
}

.custom-label textarea {
  width: 100%;
  border: 1px solid var(--border-hairline);
  background: #ffffff;
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 13px;
  color: var(--ink);
  min-height: 90px;
  resize: vertical;
}

.custom-label textarea:focus {
  border-color: var(--blue);
  outline: none;
}

/* STAGE PANEL (CENTER CANVAS) */
.stage-panel {
  display: flex;
  flex-direction: column;
}

.stage-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 18px;
}

.stage-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--muted);
  padding: 6px 10px;
  border-radius: 8px;

.stage-controls-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

/* HORIZONTAL STATUS ROW IN WHITESPACE */
.recording-status-row {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 7px 18px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 24px;
  box-shadow: 0 1px 4px rgba(15, 23, 42, 0.04);
}

.rec-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--crimson);
  animation: pulse 1s infinite;
}

.rec-time-text {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.5px;
}

.primary {
  background: var(--blue);
  color: white;
  border: none;
  padding: 13px 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 30px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.primary:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.start-button {
  min-width: 220px;
}

.record-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  width: 100%;
}

.record-help {
  margin: 0;
  max-width: 290px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  text-align: center;
}

.record-button {
  display: inline-flex;
  gap: 10px;
  align-items: center;
  justify-content: center;
  min-width: 230px;
  max-width: 100%;
  background: var(--blue);
  color: white;
  border: none;
  border-radius: 30px;
  padding: 14px 28px;
  font-weight: 600;
  font-size: 14px;
  box-shadow: 0 4px 14px var(--blue-glow);
}

.record-button:hover:not(:disabled) {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.record-button-secondary {
  min-width: 0;
