.wardrobe-app .studio-grid.stage-maximized .stage-panel { width: min(680px, 100%); justify-self: center; }

@media (max-width: 900px) {
  .wardrobe-app { padding: 0 22px; }
  .wardrobe-app .studio-grid, .wardrobe-app .studio-grid.sidebar-collapsed { grid-template-columns: minmax(260px, .85fr) minmax(360px, 1fr); column-gap: 24px; }
  .wardrobe-app .flower svg { min-height: 420px; }
  .wardrobe-app .page-heading h1 { font-size: 32px; }
}
@media (max-width: 700px) {
  .wardrobe-app { padding: 0 18px; }
  .wardrobe-app .topbar { height: 68px; }
  .wardrobe-app .brand { font-size: 20px; }
  .wardrobe-app .studio-grid, .wardrobe-app .studio-grid.sidebar-collapsed { grid-template-columns: minmax(0, 1fr); grid-template-areas: 'flower' 'copy' 'wardrobe'; min-height: 0; gap: 22px; padding: 8px 0 24px; }
  .wardrobe-app .stage-top { padding: 0 0 8px; }
  .wardrobe-app .flower svg { height: 290px; min-height: 0; }
  .wardrobe-app .page-heading h1 { font-size: 31px; }
  .wardrobe-app .wardrobe { padding: 16px 12px 14px; }
  .wardrobe-app .rail { gap: 4px; }
  .wardrobe-app .hanger-label { font-size: 10px; }
  .wardrobe-app .hanger-icon { height: 48px; }
  .wardrobe-app .wardrobe-text strong { font-size: 21px; }
  .wardrobe-app .wardrobe-text span { font-size: 12px; }
  .wardrobe-app .wardrobe-arrow { width: 32px; height: 32px; }
  .wardrobe-app .start-button { width: 100%; }
  .wardrobe-app .garden-settings { gap: 12px; margin-top: 20px; }
  .wardrobe-app .garden-active { grid-template-areas: 'copy' 'flower' 'conversation'; }
