.sound-wave span {
  width: 3px;
  height: 4px;
  border-radius: 99px;
  background: currentColor;
  transition: height 0.2s ease;
}

.sound-wave-blue { color: var(--blue); }
.sound-wave-slate { color: var(--muted); }

.sound-wave.active span {
  animation: wave 1.1s ease-in-out infinite;
}

.sound-wave.active span:nth-child(1) { animation-delay: 0.1s; }
.sound-wave.active span:nth-child(2) { animation-delay: 0.3s; }
.sound-wave.active span:nth-child(3) { animation-delay: 0.5s; }
.sound-wave.active span:nth-child(4) { animation-delay: 0.15s; }
.sound-wave.active span:nth-child(5) { animation-delay: 0.4s; }
.sound-wave.active span:nth-child(6) { animation-delay: 0.25s; }
.sound-wave.active span:nth-child(7) { animation-delay: 0.45s; }

@keyframes wave {
  0%, 100% { height: 4px; }
  50% { height: 16px; }
}

.stage-bottom {
  text-align: center;
  margin-top: auto;
  padding: 20px 0;
  z-index: 2;
}

.stage-action-center {
.session-actions button:hover:not(:disabled) {
  background: rgba(15, 23, 42, 0.045);
  color: var(--ink);
}

.session-actions .reset-button {
  border-left: 1px solid var(--border-hairline);
  padding-left: 12px;
}

/* TRANSCRIPT PANEL */
.transcript-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  font-family: var(--font-mono);
}

.turn-count-badge {
  font-size: 11px;
  font-family: var(--font-mono);
  background: rgba(15, 23, 42, 0.04);
  padding: 3px 8px;
  border-radius: 12px;
  color: var(--muted);
}

.transcript {
  flex: 1;
  overflow-y: auto;
  padding: 14px 0;
  min-height: 250px;
}

.empty-transcript {
  text-align: center;
  padding: 65px 10px 0;
}

.empty-transcript > span {
  display: inline-grid;
  place-items: center;
  width: 52px;
  height: 52px;
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  border-radius: 16px;
  color: var(--muted);
}

.empty-transcript h3 {
  font-size: 14px;
  margin: 16px 0 0;
  font-weight: 600;
  color: var(--muted);
}

/* MESSAGE BUBBLES */
.message-wrapper {
  margin-bottom: 16px;
}

.turn-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 16px 0 12px;
  position: relative;
}

.turn-divider::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--border-hairline);
}

.turn-divider-label {
  position: relative;
  background: var(--bg-core);
  color: var(--subtle);
  font-size: 10px;
  font-weight: 600;
  font-family: var(--font-mono);
  padding: 0 10px;
  letter-spacing: 0.3px;
}

.message {
  margin-bottom: 3px;
}

.message-header {
  display: flex;
  align-items: center;
  margin: 0 0 5px 3px;
}

.message-author {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--muted);
  display: block;
  font-family: var(--font-mono);
  letter-spacing: 0.3px;
}

.message p {
  margin: 0;
  border-radius: 16px 16px 16px 4px;
  padding: 12px 16px; /* 对话气泡展开 */
  background: #ffffff;
  border: 1px solid var(--border-hairline);
  font-size: 14.5px; /* 字体适度展开，阅读极舒适 */
  line-height: 1.6;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.03);
}

.message-user {
  margin-left: 28px;
}

.message-user .message-header {
  justify-content: flex-end;
  margin-right: 3px;
}

.message-user .message-author {
  color: var(--blue);
}

/* RESPONSIVE DESIGN */
@media (max-width: 1150px) {
  .app-shell { padding: 0 28px; }
  .studio-grid {
    grid-template-columns: 250px minmax(300px, 1fr) 320px;
    gap: 24px;
  }
  .scenario-panel { padding-right: 20px; }
  .transcript-panel { padding-left: 20px; }
  .avatar { width: 230px; height: 230px; }
  .aura-stage-wrapper { width: 220px; height: 220px; }
  .stage-orbit { width: 260px; height: 260px; }
  h1 { font-size: 28px; }
}

@media (max-width: 930px) {
  .studio-grid {
    grid-template-columns: 260px 1fr;
  }
  .transcript-panel {
    grid-column: 1 / -1;
    border-left: none;
    border-top: 1px solid var(--border-hairline);
    padding-left: 0;
    padding-top: 24px;
    min-height: 380px;
  }
  .report-layout { grid-template-columns: 1fr; }
  .report-side { display: none; }
}

@media (max-width: 600px) {
  .app-shell { padding: 0 16px; }
  .topbar { height: 64px; }
  .brand { font-size: 19px; }
  .page-heading { padding: 20px 0 16px; }
  h1 { font-size: 24px; }
  .session-chip { display: none; }
  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 22px;
  }
  .scenario-panel {
    border-right: none;
    padding-right: 0;
    border-bottom: 1px solid var(--border-hairline);
    padding-bottom: 18px;
  }
  .scenario-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .transcript-panel {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--border-hairline);
    padding-top: 18px;
  }
  .avatar { width: 230px; height: 230px; }
