  white-space: pre-wrap;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.03);
}

.message-user {
  margin-left: 28px;
}

.message-user .message-header {
  justify-content: flex-end;
  margin-right: 3px;
}

.message-user .message-author {
